(() => {
  const token=localStorage.getItem('spw_admin_token')||localStorage.getItem('spw_staff_token')||localStorage.getItem('spw_user_token');
  if(!token)return;
  const API=(window.SPW_APP?.API_BASE||location.origin).replace(/\/$/,'').replace(/\/api$/i,'');
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const money=v=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(Number(v||0));
  const statusLabel=s=>String(s||'pending_payment').replace(/_/g,' ').replace(/\b\w/g,c=>c.toUpperCase());
  async function api(path,options={}){const headers={Authorization:`Bearer ${token}`,...(options.body?{'Content-Type':'application/json'}:{})};const r=await fetch(API+path,{...options,headers});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.message||'Request failed.');return d;}
  function render(projects){
    const root=document.getElementById('staffProjectsList');if(!root)return;
    if(!projects.length){root.innerHTML='<div class="card panel"><p>No customer projects have been created yet.</p></div>';return;}
    root.innerHTML=projects.map(p=>`<article class="card panel" style="margin-bottom:12px">
      <div style="display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap"><div><span class="tag">Customer Project</span><h3 style="margin:7px 0">${esc(p.title)}</h3><p style="font-size:11px;color:var(--muted)">${esc(p.clientName)} · ${esc(p.clientEmail)}</p></div><span class="status ${p.status==='delivered'||p.status==='completed'?'active-status':'pending'}">${esc(statusLabel(p.status))}</span></div>
      <p style="font-size:12px">${esc(p.description||'')}</p>
      <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:12px 0"><div><small>Total</small><strong style="display:block">${money(p.totalAmount)}</strong></div><div><small>Paid</small><strong style="display:block">${money(p.paidAmount)}</strong></div><div><small>Remaining</small><strong style="display:block">${money(p.remainingAmount)}</strong></div></div>
      <div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:10px"><select class="input spw-project-status" data-id="${p.id}" style="max-width:190px"><option value="pending_payment">Pending Payment</option><option value="in_progress">In Progress</option><option value="ready_for_delivery">Ready for Delivery</option><option value="delivered">Delivered</option><option value="completed">Completed</option></select><button class="btn secondary spw-status-save" data-id="${p.id}">Save Status</button></div>
      <div style="border-top:1px solid var(--border);padding-top:12px"><strong>Deliver Project</strong><div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:8px"><input class="input spw-delivery-url" data-id="${p.id}" placeholder="Delivery link (optional)" value="${esc(p.deliveryUrl||'')}"><input class="input spw-delivery-file" data-id="${p.id}" type="file" accept=".zip,.pdf,.doc,.docx,.txt,.apk,.ipa"></div><textarea class="input spw-delivery-notes" data-id="${p.id}" rows="3" style="width:100%;margin-top:8px" placeholder="Delivery notes / instructions">${esc(p.deliveryNotes||'')}</textarea><button class="btn spw-deliver" data-id="${p.id}" style="margin-top:8px">Deliver to Customer</button></div>
    </article>`).join('');
    projects.forEach(p=>{const s=document.querySelector(`.spw-project-status[data-id="${p.id}"]`);if(s)s.value=p.status;});
    root.querySelectorAll('.spw-status-save').forEach(b=>b.onclick=async()=>{try{const s=root.querySelector(`.spw-project-status[data-id="${b.dataset.id}"]`);await api(`/api/projects/${b.dataset.id}`,{method:'PATCH',body:JSON.stringify({status:s.value})});await load();}catch(e){alert(e.message);}});
    root.querySelectorAll('.spw-deliver').forEach(b=>b.onclick=async()=>{try{const id=b.dataset.id;const file=root.querySelector(`.spw-delivery-file[data-id="${id}"]`)?.files?.[0];if(file&&file.size>20*1024*1024)throw new Error('Delivery files must be 20 MB or smaller.');const read=f=>new Promise((resolve,reject)=>{if(!f)return resolve('');const r=new FileReader();r.onload=()=>resolve(String(r.result||''));r.onerror=()=>reject(new Error('Could not read delivery file.'));r.readAsDataURL(f);});b.disabled=true;b.textContent='Delivering…';const fileBase64=await read(file);const d=await api(`/api/projects/${id}/deliver`,{method:'POST',body:JSON.stringify({deliveryNotes:root.querySelector(`.spw-delivery-notes[data-id="${id}"]`).value,deliveryUrl:root.querySelector(`.spw-delivery-url[data-id="${id}"]`).value,fileName:file?.name||'',mimeType:file?.type||'',fileBase64})});alert(d.message||'Project delivered.');await load();}catch(e){alert(e.message);b.disabled=false;b.textContent='Deliver to Customer';}});
  }
  async function load(){const root=document.getElementById('staffProjectsList');if(!root)return;try{const d=await api('/api/projects/admin');render(d.projects||[]);}catch(e){root.innerHTML=`<div class="card panel"><p>${esc(e.message)}</p></div>`;}}
  document.getElementById('createProjectForm')?.addEventListener('submit',async e=>{e.preventDefault();const status=document.getElementById('createProjectStatus');try{const data=Object.fromEntries(new FormData(e.currentTarget).entries());data.totalAmount=Number(data.totalAmount);const d=await api('/api/projects',{method:'POST',body:JSON.stringify(data)});status.textContent=d.message||'Project created.';status.className='status completed';e.currentTarget.reset();await load();}catch(err){status.textContent=err.message;status.className='status';}});
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',load,{once:true});else load();
  window.SPW_PROJECT_MANAGEMENT={load};
})();